INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Makaimura Gaiden: The Demon Darkness', 'Makaimura Gaiden: The Demon Darkness is a action platforming game released in Japan for the Game Boy in 1993. It is the second title for the handheld platform featuring the demon Red Arremer (also known outside of Japan as Firebrand, a boss from Ghosts ''n Goblin) as the player character. The game was originally set to be localized in English as Gargoyle''s Quest II, but North American release plans were eventually cancelled.' FROM games WHERE igdb_id = 84640 ON CONFLICT (game_id, language_code) DO NOTHING;
