INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 7th Guest', 'The 7th Guest is a horror adventure described as "the first Interactive Drama", with plentiful pre-rendered 3D graphics, live action video clips, and an original, orchestrated musical score. The atmosphere is dense, the puzzles difficult and the experience as a whole is completely horrifying.' FROM games WHERE igdb_id = 323 ON CONFLICT (game_id, language_code) DO NOTHING;
