INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eternal-champions', 4477, '1993-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2er8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30j2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternal Champions', 'Sega released Eternal Champions for their Mega Drive/Genesis in 1993, hoping to capitalize on the fighting game mania that the game industry was in the midst of following the massive success of Street Fighter II (1991) and Mortal Kombat (1992). The game tried to set itself apart with unique features like a heavier emphasis on its story, characters pulled from different time periods, reflectable projectiles, force fields, fighters that carried weapons, a training mode where players had to defend themselves against robotic traps, a novel method of executing moves, and elaborate stage-specific finishing moves called "Overkills".' FROM games WHERE igdb_id = 4477 ON CONFLICT (game_id, language_code) DO NOTHING;
