INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aero the Acro-Bat', 'You play as bat Aero, who have to stop the mad scientist Edgar Ektor, who is trying to rid the world of amusement and fun. So you jump through the circus-style levels, using different kinds of machines such as catapults, cannons, bubble machines, platforms, etc., collecting various power-ups such as cheese, soda, keys, clocks, etc. and avoiding lethal obstacles.' FROM games WHERE igdb_id = 5348 ON CONFLICT (game_id, language_code) DO NOTHING;
