INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z Gaiden: Saiya-jin Zetsumetsu Keikaku', 'You control five various Dragon Ball characters in this game: Son Goku, Son Gohan, Piccolo, Vegeta, and Future Trunks. The game is based on training your characters, and fighting with them. The outcomes of the fights are determined by the player choosing different cards he has at his disposal, and combining them to create various attacks.' FROM games WHERE igdb_id = 48681 ON CONFLICT (game_id, language_code) DO NOTHING;
