INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles III: Radical Rescue', 'The whole sewer crew, except Michelangelo, is captured in a most heinous hideout. Who could be behind this travesty? Who else. Shredder has returned as Cyber Shredder - half-man, half-machine and he''s created this twisty-turny fun house of Turtle torture. Use Turtle strategy and all new moves to help Michelangelo rescue the gang from Cyber Shredder''s Fortress.' FROM games WHERE igdb_id = 48927 ON CONFLICT (game_id, language_code) DO NOTHING;
