INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Street Fighter II: The New Challengers', 'Super Street Fighter II: The New Challengers is a 2D fighting game that expands the original Street Fighter II roster with four new characters: Cammy, Dee Jay, T. Hawk, and Fei Long. Players choose from 16 fighters, each with unique moves, to compete in one-on-one matches. The game introduces updated graphics, rebalanced gameplay, and new special moves, continuing the World Warrior Tournament storyline.' FROM games WHERE igdb_id = 12860 ON CONFLICT (game_id, language_code) DO NOTHING;
