INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('uncharted-waters-new-horizons', 38412, '1993-02-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ba8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scz2px.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted Waters: New Horizons', 'In the first Uncharted Waters game, it was the 15th century and the New World was discovered. Now in New Horizons, it is the early 16th century and the age of exploration and sea trade is underway. Players choose from any one of six adventurers (scenarios), each with their own distinctive but intertwining plot, to embark on a quest of sailing, seamanship and exploration. The six characters are:Joao Franco is the son of Duke Leon Franco, the hero of the first Uncharted Waters game and an influential man in Portugal. His father wants to make him into a strong man and so decides to send him out to sea. Young Joao is tasked with learning the skills of the sailor (he is the only character who starts at level one) and embarking on a quest of discovery; reaching the far east and eventually looking for the secret of Atlantis.
