INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superfrog', 'Superfrog is a 2D platformer developed and published by Team17, originally released for the Amiga in 1993. Players control a super-powered frog who must traverse a variety of levels, overcome obstacles, and defeat enemies using different power-ups. The game is noted for its challenging platforming sections and a humorous, whimsical design, and it has since been ported to multiple platforms.' FROM games WHERE igdb_id = 8872 ON CONFLICT (game_id, language_code) DO NOTHING;
