INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inspector Gadget', 'Inspector Gadget is on yet another mission against the evil Doctor Claw and his army of M.A.D. (Mean And Dirty) agents. This time it''s personal because Doctor Claw has captured Gadget''s niece, Penny. With the help of his trusty dog, Brain, and his suit full of special gadgets, Inspector Gadget must save Penny and defeat Doctor Claw and his minions!' FROM games WHERE igdb_id = 4859 ON CONFLICT (game_id, language_code) DO NOTHING;
