INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('james-pond-3-operation-starfish', 5926, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co84wr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nbb00jis6qkrhna4ygkd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Pond 3: Operation Starfish', 'Unlike the first game of the series, that was a mission-based game, and the second one, where your character had unique abilities such as observing the whole level and growing to unlimited height, James Pond 3 is a standard jump and run platform game. Pond can run very quickly (by holding down the A button) through large levels, which often contain steep mountain sides and other tricky areas. Once again, he has to oppose the evil scientist Maybe and his minions.' FROM games WHERE igdb_id = 5926 ON CONFLICT (game_id, language_code) DO NOTHING;
