INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Force: The Sword of Hajya', 'The peaceful kingdom of Cypress has suddenly been disrupted by the corrupt ambition of the evil King Iom. Terror rampages across the land. The Castle of Cypress is invaded and the magical Sword of Hajya is taken! It will take strength, courage, agility and your keen sense of strategy to defy this ominous power.' FROM games WHERE igdb_id = 46360 ON CONFLICT (game_id, language_code) DO NOTHING;
