INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman Returns', 'Closer in style and gameplay to the Double Dragon series. The player only has one life bar (which can be expanded through health packs). It implements a password-save system. Of special note are the two side-scrolling racing levels in which the player controls the Batmobile and the Batskiboat.' FROM games WHERE igdb_id = 121244 ON CONFLICT (game_id, language_code) DO NOTHING;
