INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-ren-and-stimpy-show-veediots', 7989, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2doj.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ren & Stimpy Show: Veediots!', 'Veediots! lets the player experience four classic episodes of the Ren & Stimpy Show. One is the episode, "The Boy Who Cried Rat", where the player takes control of Ren, who''s dressed like a mouse, in which he has to reach the end of a house while avoiding obstacles and enemies as well as Stimpy. Towards the end of this stage, the player must travel through Stimpy''s mouth in order to complete the stage by avoiding various pitfalls and obstacles.
