INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SegaSonic the Hedgehog', 'SegaSonic the Hedgehog is an isometric platforming game with three characters who shares identical controls and abilities. The characters are controlled with one action button which lets the player perform a spin jump, and a trackball which is used to move the characters around. Each trackball and corresponding action button are color-coded, meaning the blue ones are for Sonic, red ones are for Mighty and yellow ones are for Ray.
