INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ishar-2-messengers-of-doom', 2523, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jj0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvkb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ishar 2: Messengers of Doom', 'Ishar 2 was published in 1993 on Amiga, Atari ST and DOS. In Ishar 2, the player starts with the character of Zubaran, who is the new lord of Ishar. He receives a vision that tells him to defeat the sorcerer Shandar. It is also possible to import a party of characters from the first Ishar. The game now takes place on an archipelago, each island bearing the name of one of Jarel''s companions. Each island also features a different type of landscape: Irvan''s island is covered with swamps, Akeer''s and Otbar''s are underground complexes, Zach''s island is covered by a city, Jon''s is mountainous, and Thorm''s has treetop gangways in a forest.
