INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battletoads / Double Dragon', 'Battletoads & Double Dragon - The Ultimate Team is the fourth game in the Battletoads series. It is a crossover with the Double Dragon series of beat ''em up games developed by Technos Japan. It was released for the NES, with ports for the Super NES, Sega Mega Drive/Genesis, and Nintendo Game Boy. Despite the presence of the Double Dragon characters, Technos Japan had no actual role in the game''s development.' FROM games WHERE igdb_id = 7776 ON CONFLICT (game_id, language_code) DO NOTHING;
