INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kid-dracula', 1125, '1993-01-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6vv9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sk1q5ealy5mlzcl4npp9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Dracula', 'His pearly fangs drive the girls wild, while his dead-of-the-party sense of humor makes them scream. He''s Kid Dracula, star of the mythical Transylvania 92010, and the coolest living corpse ever to stake his claim on the Game Boy. If you thought Mario had a way with magic, you should see junior jugular''s spellbinding powers, including the mesmerizing bat transformation. Poof! Nobody wings it better than Kid Drac.
