INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunting Starring Polterguy', 'Scare the evil, greedy Sardinis out of their houses by turning everyday household objects into something scary, funny or just plain gross. Or use your special spells to really send ''em shrieking. But you gotta hurry, ''cause your ectoplasm may run out! 16 megs of cool graphics, gross special effects and blood-curdling sounds. Unique 3/4 view perspective. Over 400 scary, funny or gross fright items, each causing something different to happen. Five special spells: Zom-B-Ize, Supr-Scare, Boo-Doo, Ecto-Xtra and Dog-Off. "Killer" dungeon with 12 different paths!' FROM games WHERE igdb_id = 8100 ON CONFLICT (game_id, language_code) DO NOTHING;
