INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eye of the Beholder III: Assault on Myth Drannor', 'Eye of the Beholder III : Assault on Myth Drannor is an all 3-D, Legend Series computer role-playing adventure based on the popular Advanced Dungeons & Dragons 2nd Edition rules and on an original story created for this game . The action takes place in and around Myth Drannor, located in TSR''s Forgotten Realms game world.
