INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Punisher', 'The Punisher is a 1993 beat ''em up arcade game. It stars the Marvel Comics'' anti-hero the Punisher and co-stars S.H.I.E.L.D. agent Nick Fury as the second player''s character as they embark on a mission to kill the crime lord the Kingpin and bring down his organization. Whilst following the same general formula as Capcom''s previous beat ''em ups, the game has a range of usable weapons and a comics-style presentation.' FROM games WHERE igdb_id = 19768 ON CONFLICT (game_id, language_code) DO NOTHING;
