INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Breed II: The Horror Continues', 'Alien Breed II: The Horror has Gauntlet-influenced gameplay, similar to the original Alien Breed (and the Alien Breed Special Edition ''92), but with many new features. As an Interplanetary Corps soldier, you must visit a remote alien-infested colony and destroy the alien invaders. The game is split over 17 zones, each featuring numerous different aliens. As you go through the game you collect credits, which can be traded for weapons, ammunition and other enhancements through the in-game computers. Keys are collected as you progress, which must be used wisely, as there are many rooms containing bonuses that don’t have to be entered.' FROM games WHERE igdb_id = 14241 ON CONFLICT (game_id, language_code) DO NOTHING;
