INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lands of Lore: The Throne of Chaos', 'Lands of Lore: The Throne of Chaos takes you on an adventure: save the dying king and stop the evil sorceress Scotia’s Dark Army. Your band of heroes will travel through a vast fantasy word full of mysterious places, dangerous monsters, and hidden treasures in a quest to find a way to defeat the immortal evil enchantress and save the world.' FROM games WHERE igdb_id = 2528 ON CONFLICT (game_id, language_code) DO NOTHING;
