INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazon Trail', 'Amazon trail is an educational adventure game. You venture back through time to meet the Inca king and deliver him the cinchona plant together with many valuable gifts. The knowledge of the rain forest is the key to successes. Your main goal is to survive the journey and, if possible, bring as many additional gifts to the Inca king.' FROM games WHERE igdb_id = 2306 ON CONFLICT (game_id, language_code) DO NOTHING;
