INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Cars', 'Racing game for the SNES developed by Malibu. Can be played by 1 or 2 players. The game is set in a post-apocalyptic world in which the sport of choice is a violent auto race called "Battle Cars." The player can select from three vehicles at the start of the game in a variety of colors, to be played for the duration of the game. The choices are a spiked vehicle, a hot rod, and a formula one-style race car.' FROM games WHERE igdb_id = 36729 ON CONFLICT (game_id, language_code) DO NOTHING;
