INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('raging-fighter', 48921, '1993-03-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9i1k.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raging Fighter', 'If you think you''re tough enough to rumble with the best fighters in the world, take your best shot in RAGING FIGHTER. Choose from seven different brawlers Vandal, Aska, Ruoh, Shades, Miyabi, Tao, and Bulk as you take it to the competition and show em who''s boss. There are four different tournament styles to play in, making for intensely high replay value and variety. Each of the seven fighters brandishes a few special moves that are all their own, making for original fights every time out. Of course, there are the requisite punches and kicks, but mastering your own fighter''s combos will lead you to easier victory. Play against the computer, or hook up with a friend via a link cable and scrap it out for bragging rights.' FROM games WHERE igdb_id = 48921 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48921 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
