INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plumbers Don''t Wear Ties', 'He''s a plumber, she''s a daddy''s girl. Only you can get them together, or tear them apart! Plumbers have everything: Greed, sex, spirituality, white-knuckle chases, shameful propositions, a nun, humor, true love, jaded love, jealousy, taut action, comedy, a bad guy, a good guy, a hero, spine-tingling suspense, a hot babe, brazen bravado, a damsel in distress, and a Hollywood ending! Plays like a game... feels like a movie!' FROM games WHERE igdb_id = 4251 ON CONFLICT (game_id, language_code) DO NOTHING;
