INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pierre le Chef is... Out to Lunch', 'Pierre le Chef is touring the world preparing his dishes, but his ingredients have escaped and he must capture them. Pierre must watch out for bacteria, insects, and his arch-rival, Le Chef Noir. Noir, an evil chef jealous of Pierre''s success, wants to ruin his career by releasing all of his gathered ingredients.' FROM games WHERE igdb_id = 39042 ON CONFLICT (game_id, language_code) DO NOTHING;
