INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color a Dinosaur', 'Color a Dinosaur is an electronic coloring book designed for kids ages 3 to 6. The game provides 16 different dinosaurs which can be colored in with a variety of colors and patterns. There are two coloring modes available: free form mode where you control a pencil and select the region to be colored, or automatic mode where the computer selects a region and you only have to select a color.' FROM games WHERE igdb_id = 8202 ON CONFLICT (game_id, language_code) DO NOTHING;
