INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Toon Adventures: Buster''s Hidden Treasure', 'Hit it big when you join Buster Bunny on a 33 stage hunt for treasure. So loaded with hare-raising animation, it''s like playing in a whacked-out Tiny Toon cartoon! Do you dare to set paw on this mysterious island? Trip through 7 tangly territories that include an overly-enchanted forest, caverns of bubbling lava-lava, secret underground seas, plains that are just plain crazy, a freaky factory, a mega mountain and a spooky shipwreck rumored to be dripping in 14 carrot gold! Save Babs Bunny and the rest of your pals along the way and you''ll really see some kooky island hopping. With Gogo Dodo as your guide, you can be sure this adventure is packed with tricks, traps, and hidden bonus areas!' FROM games WHERE igdb_id = 8049 ON CONFLICT (game_id, language_code) DO NOTHING;
