INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey''s Safari in Letterland', 'Endlessly entertaining, MICKEY''S SAFARI IN LETTERLAND is a delightful way to help children improve important early recognition skills as they have fun with Mickey and his Disney pal, Goofy! 6 Exciting animated worlds of adventure await all who join Mickey on his safari to find the lost letter tablets and return them to the museum. Hidden surprises are scattered throughout each level--including rare "alphabet jewels" that spell out words and add extra challenge to the fun.' FROM games WHERE igdb_id = 48168 ON CONFLICT (game_id, language_code) DO NOTHING;
