INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantastic Dizzy', 'Dizzy is an egg living in a world of magic and fantasy. The basic concept of the game is to move around the world, finding various items and collectibles, and to use them in the right locations. Dizzy has no special skills or abilities, save for his remarkable feats of somersaulting, and must solve all problems he faces with the clever use of one or more items.' FROM games WHERE igdb_id = 12089 ON CONFLICT (game_id, language_code) DO NOTHING;
