INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man 3: Invasion of Spider-Slayers', 'Spidey''s in a web of trouble! Razor-winged, bolt-firing, mechanoid Spider-Slayers want to slide and dice him! Electro and Scorpion are trying to fry him with bolts of electricity! But on-screen Spider-Sense and devastating new combat moves mean it ain''t over ''till Spidey says it''s over!' FROM games WHERE igdb_id = 48926 ON CONFLICT (game_id, language_code) DO NOTHING;
