INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimFarm', 'SimFarm was developed by Maxis as a spinoff of SimCity, and allowed the player to simulate the running of a farm. It was released in 1993 for PC Dos, and was released a year later for Macintosh. It has become a classic, and began the subsequent development of the farm simulation subgenre, although Maxis did not make any sequel to the game in the way they have for SimCity.' FROM games WHERE igdb_id = 8804 ON CONFLICT (game_id, language_code) DO NOTHING;
