INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF Royal Rumble', 'Control one of twelve World Wrestling Federation stars in a "no holds barred brawl" -- in other words, do whatever moves you want, from choke holds, piledrivers, and even chair slams, until your opponent is knocked out. You can even go outside the ring if you like. Several modes of play are available, including one-on-one, tag team (two-on-two), and three-on-three tag team. You can play as the following WWF wresters: Bret Hart, Razor Ramon, Randy Savage, Shawn Michaels, The Undertaker, Tatanka, Mr. Perfect, Crush, Ric Flair, Yokozuna, Ted Dibiase, and Lex Luger.' FROM games WHERE igdb_id = 38408 ON CONFLICT (game_id, language_code) DO NOTHING;
