INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barkley: Shut Up and Jam!', 'In the game you play street basketball two-on-two with your friends or with the computer. So there are no referees, no fouls, and no shot clock, but the teams called by the names of cities such as Phoenix or Chicago. You can choose your player from 16 available players, including Barkley himself.' FROM games WHERE igdb_id = 4520 ON CONFLICT (game_id, language_code) DO NOTHING;
