INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubsy in Claws Encounters of the Furred Kind', 'Bubsy in Claws Encounters of the Furred Kind, known as Bubsy for short, is a platform video game released by Accolade in the early 1990s. It is the first game in the Bubsy series of video games. The game''s name is a play on words in reference to Close Encounters of the Third Kind, with the game revolving around Bubsy defending the planet''s supply of yarnballs from alien invaders. The game received a sequel, Bubsy 2, in 1994.' FROM games WHERE igdb_id = 7804 ON CONFLICT (game_id, language_code) DO NOTHING;
