INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lamborghini: American Challenge', 'The game is an upgrade from Titus Interactive''s previous entry in the Crazy Cars franchise, Crazy Cars III. It adds a two player mode and a few more options, the game''s most notable feature is its Jazz Fusion soundtrack. Another feature of this game is that your car is damaged in every beat you suffer, and so that it goes back to normal state only by paying a little money later to repair it.' FROM games WHERE igdb_id = 27525 ON CONFLICT (game_id, language_code) DO NOTHING;
